package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.widget.*;import java.util.*;
public final class TrafficMapActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);ProjectRepository.init(this);ProxyHistoryRepository.init(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Traffic Map");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);TextView n=new TextView(this);n.setText("App → host → protocol relationship map for the active project.");r.addView(n);TextView body=new TextView(this);body.setTypeface(Typeface.MONOSPACE);body.setTextIsSelectable(true);body.setText(build());ScrollView s=new ScrollView(this);s.addView(body);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 private String build(){Map<String,Map<String,Map<String,Integer>>>m=new TreeMap<>();for(ProxyEvent e:ProxyHistoryRepository.snapshotActiveProject()){String app=e.appLabel.isEmpty()?(e.source.isEmpty()?"ReqLens":e.source):e.appLabel;String host=e.host.isEmpty()?e.ip:e.host;if(host.isEmpty())host="(unknown)";String proto=e.protocol.isEmpty()?"unknown":e.protocol;m.computeIfAbsent(app,k->new TreeMap<>()).computeIfAbsent(host,k->new TreeMap<>()).merge(proto,1,Integer::sum);}StringBuilder s=new StringBuilder();for(Map.Entry<String,Map<String,Map<String,Integer>>>a:m.entrySet()){s.append(a.getKey()).append('\n');for(Map.Entry<String,Map<String,Integer>>h:a.getValue().entrySet()){s.append("  └─ ").append(h.getKey()).append('\n');for(Map.Entry<String,Integer>p:h.getValue().entrySet())s.append("      ").append(p.getKey()).append(" × ").append(p.getValue()).append('\n');}}return s.length()==0?"No traffic yet":s.toString();}
}
